 BIT240098_Username NVARCHAR(100) NOT NULL UNIQUE,
 BIT240098_PasswordHash NVARCHAR(MAX) NOT NULL,
 BIT240098_Role NVARCHAR(20) NOT NULL CHECK (BIT240098_Role IN ('User','Admin'))
